// phone remote: a token-protected web page that runs `codex exec` in this repo
const http = require("http");
const crypto = require("crypto");
const { spawn } = require("child_process");

const TOKEN = process.env.REMOTE_TOKEN;
const HOST = process.env.REMOTE_HOST || "127.0.0.1";
const PORT = Number(process.env.REMOTE_PORT || 8787);
if (!TOKEN || TOKEN.length < 16) {
  console.error("Set REMOTE_TOKEN (16+ chars) before starting the remote.");
  process.exit(1);
}

const PAGE = `<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1">
<title>codex remote</title>
<style>body{font:16px system-ui;margin:12px}textarea,button{width:100%;font:inherit;box-sizing:border-box}
textarea{height:7em}button{padding:12px;margin-top:8px}pre{white-space:pre-wrap;background:#111;color:#ddd;padding:8px;min-height:8em}</style>
<textarea id="p" placeholder="Prompt for codex"></textarea>
<button id="go">Run</button><pre id="out"></pre>
<script>
const token = new URLSearchParams(location.hash.slice(1)).get("t") || "";
go.onclick = async () => {
  go.disabled = true; out.textContent = "";
  try {
    const res = await fetch("/run", { method: "POST", headers: { Authorization: "Bearer " + token }, body: p.value });
    const reader = res.body.getReader(), dec = new TextDecoder();
    for (;;) { const { done, value } = await reader.read(); if (done) break; out.textContent += dec.decode(value, { stream: true }); }
  } catch (e) { out.textContent += "\\n[error] " + e; }
  go.disabled = false;
};
</script>`;

function authorized(req) {
  const given = Buffer.from(String(req.headers.authorization || ""));
  const expected = Buffer.from("Bearer " + TOKEN);
  return given.length === expected.length && crypto.timingSafeEqual(given, expected);
}

let busy = false;

http
  .createServer((req, res) => {
    if (req.method === "GET" && req.url === "/") {
      res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
      return res.end(PAGE);
    }
    if (req.method !== "POST" || req.url !== "/run") {
      res.writeHead(404);
      return res.end();
    }
    if (!authorized(req)) {
      res.writeHead(401);
      return res.end("unauthorized\n");
    }
    if (busy) {
      res.writeHead(409);
      return res.end("codex is already running\n");
    }

    let prompt = "";
    req.on("data", (chunk) => (prompt += chunk));
    req.on("end", () => {
      if (!prompt.trim()) {
        res.writeHead(400);
        return res.end("empty prompt\n");
      }
      busy = true;
      res.writeHead(200, { "Content-Type": "text/plain; charset=utf-8" });
      console.log(`[remote] run: ${prompt.slice(0, 80)}`);
      // Fixed args only; the prompt goes over stdin ("-"), so it never reaches a shell.
      // shell is needed on Windows because codex is installed as a .cmd shim.
      const child = spawn("codex", ["exec", "--sandbox", "workspace-write", "-"], {
        cwd: __dirname,
        shell: process.platform === "win32",
      });
      child.stdin.end(prompt);
      child.stdout.on("data", (d) => res.write(d));
      child.stderr.on("data", (d) => res.write(d));
      child.on("error", (e) => res.write(`\n[error] ${e.message}\n`));
      child.on("close", (code) => {
        busy = false;
        res.end(`\n[exit ${code}]\n`);
      });
    });
  })
  .listen(PORT, HOST, () => console.log(`[remote] listening on http://${HOST}:${PORT}`));

